        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('10021111-0000-4000-8000-000000000001', 'If HCF(26, 91) = 13, then LCM(26, 91) is:', '{"A":"169","B":"182","C":"2366","D":"91"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Real Numbers', 1, 'LCM = (26 × 91)/13 = 182.', NULL, NULL, 'LCM = (26 × 91)/13 = 182.', 'EASY', true),
        ('10021111-0000-4000-8000-000000000002', 'The exponent of 2 in the prime factorisation of 144 is:', '{"A":"2","B":"3","C":"4","D":"5"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Real Numbers', 1, '144 = 2⁴ × 3², so exponent of 2 is 4.', NULL, NULL, '144 = 2⁴ × 3², so exponent of 2 is 4.', 'EASY', true),
        ('10021111-0000-4000-8000-000000000003', 'The product of a non-zero rational number and an irrational number is always:', '{"A":"Rational","B":"Irrational","C":"An integer","D":"Zero"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Real Numbers', 1, 'Non-zero rational × irrational = irrational.', NULL, NULL, 'Non-zero rational × irrational = irrational.', 'EASY', true),
        ('10021111-0000-4000-8000-000000000004', 'What is the HCF of the smallest prime number and the smallest composite number?', '{"A":"1","B":"2","C":"4","D":"6"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Real Numbers', 1, 'Smallest prime = 2, smallest composite = 4 -> HCF(2, 4) = 2.', NULL, NULL, 'Smallest prime = 2, smallest composite = 4 -> HCF(2, 4) = 2.', 'EASY', true),
        ('10021111-0000-4000-8000-000000000005', 'For any natural number n, 6ⁿ ends with the digit 0 if its prime factorisation contains:', '{"A":"2 and 3","B":"2 and 5","C":"3 and 5","D":"2 only"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Real Numbers', 1, '6ⁿ = (2×3)ⁿ lacks factor 5, hence never ends in 0.', NULL, NULL, '6ⁿ = (2×3)ⁿ lacks factor 5, hence never ends in 0.', 'EASY', true),
        ('10021111-0000-4000-8000-000000000006', 'Assertion (A): The number 4ⁿ cannot end with the digit zero for any natural number n.
        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('10021111-0000-4000-8000-0000000000c9', 'A tent is in the shape of a cylinder surmounted by a conical top. If the height and diameter of the cylindrical part are 2.1 m and 4 m respectively, and the slant height of the top is 2.8 m, find the area of the canvas used for making the tent. Also, find the cost of the canvas of the tent at the rate of ₹500 per m². (Use π = 22/7)', NULL, NULL, 'LA', 'Mathematics', 'Surface Areas & Volumes', 5, 'Radius r = 4/2 = 2 m, cylinder height h = 2.1 m, slant height of cone l = 2.8 m.
